export const API = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000/api';
export type Summary = { orders: number; products: number; revenue: number; pending: number };
export type Order = { id: string; orderNumber: string; customerName: string; phone: string; city: string; total: number; status: string; paymentMethod: string; paymentNumber?: string; transactionId?: string; createdAt: string; items: { name: string; size: string; quantity: number }[] };
export type Product = { id: string; name: string; slug: string; price: number; category: string; inventory: number; published: boolean; images: string[]; colorName: string; colorHex: string; colors: { name: string; hex: string }[]; sizes: string[]; tags: string[]; fabric: string; details: string[] };
export async function getSummary(): Promise<Summary> { try { const r = await fetch(`${API}/dashboard/summary`, { cache: 'no-store' }); if (!r.ok) throw new Error(); return r.json(); } catch { return { orders: 0, products: 0, revenue: 0, pending: 0 }; } }
export async function getOrders(): Promise<Order[]> { try { const r = await fetch(`${API}/orders`, { cache: 'no-store' }); if (!r.ok) throw new Error(); return r.json(); } catch { return []; } }
export async function getProducts(): Promise<Product[]> { try { const r = await fetch(`${API}/products`, { cache: 'no-store' }); if (!r.ok) throw new Error(); return r.json(); } catch { return []; } }
export async function getBanners(): Promise<any[]> { try { const r = await fetch(`${API}/banners`, { cache: 'no-store' }); return r.ok ? r.json() : []; } catch { return []; } }
export async function getUsers(): Promise<any[]> { try { const r = await fetch(`${API}/users`, { cache: 'no-store' }); return r.ok ? r.json() : []; } catch { return []; } }
export async function getSettings(): Promise<Record<string, string>> { try { const r = await fetch(`${API}/settings`, { cache: 'no-store' }); return r.ok ? r.json() : {}; } catch { return {}; } }
