import { ArrowUpRight, Clock3, PackageCheck, ShoppingBag, TrendingUp } from 'lucide-react';
import PageHeader from '@/components/page-header';
import { getOrders, getSummary } from '@/lib/api';

const money = (n: number) => `৳${n.toLocaleString('en-US')}`;
export default async function Dashboard() { const [summary, orders] = await Promise.all([getSummary(), getOrders()]); return <><PageHeader eyebrow="Thursday, October 1, 2026" title="Good morning, admin." action={<button className="rounded-full bg-ink px-5 py-3 text-xs font-bold text-white">View storefront <ArrowUpRight className="ml-2 inline" size={15} /></button>} /><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={<ShoppingBag />} label="Total orders" value={summary.orders} note="All time" /><Stat icon={<TrendingUp />} label="Revenue" value={money(summary.revenue)} note="Excluding cancelled" /><Stat icon={<PackageCheck />} label="Products" value={summary.products} note="In catalogue" /><Stat icon={<Clock3 />} label="Needs attention" value={summary.pending} note="Pending orders" alert /></section><section className="mt-8 grid gap-5 xl:grid-cols-[1.45fr_1fr]"><div className="card p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg font-black tracking-[-.04em]">Recent orders</h2><p className="mt-1 text-xs text-muted">Latest activity from your storefront</p></div><a className="text-xs font-bold underline" href="/orders">View all</a></div><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="border-b border-line text-[10px] font-bold tracking-[.16em] text-muted uppercase"><th className="pb-3">Order</th><th className="pb-3">Customer</th><th className="pb-3">Date</th><th className="pb-3">Total</th><th className="pb-3">Status</th></tr></thead><tbody>{orders.slice(0, 6).map(o => <tr className="border-b border-line last:border-0" key={o.id}><td className="py-4 font-bold">{o.orderNumber}</td><td className="py-4">{o.customerName}</td><td className="py-4 text-muted">{new Date(o.createdAt).toLocaleDateString()}</td><td className="py-4 font-bold">{money(o.total)}</td><td className="py-4"><Status value={o.status} /></td></tr>)}{orders.length === 0 && <tr><td className="py-10 text-center text-muted" colSpan={5}>Connect PostgreSQL and seed the database to see orders.</td></tr>}</tbody></table></div></div><div className="card dot-grid min-h-[320px] p-6"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold tracking-[.16em] text-muted uppercase">Store pulse</p><h2 className="mt-2 text-2xl font-black tracking-[-.06em]">Keep the drop moving.</h2></div><div className="grid size-10 place-items-center rounded-full bg-accent"><TrendingUp size={19} /></div></div><p className="mt-24 max-w-[250px] text-sm leading-relaxed text-muted">Your storefront, catalogue, and order operations all live in one place.</p></div></section></> }
function Stat({ icon, label, value, note, alert }: { icon: React.ReactNode; label: string; value: string | number; note: string; alert?: boolean }) { return <div className="card stat"><div className="mb-5 flex items-center justify-between"><span className="grid size-9 place-items-center rounded-lg bg-[#f0f0eb]">{icon}</span>{alert && <span className="rounded-full bg-[#fff4c9] px-2 py-1 text-[10px] font-bold">Action</span>}</div><p className="text-[11px] font-bold tracking-[.12em] text-muted uppercase">{label}</p><p className="mt-2 text-3xl font-black tracking-[-.06em]">{value}</p><p className="mt-2 text-xs text-muted">{note}</p></div> }
function Status({ value }: { value: string }) { return <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase ${value === 'PENDING' ? 'bg-[#fff4c9]' : value === 'DELIVERED' ? 'bg-[#dff5df]' : 'bg-[#ededed]'}`}>{value.toLowerCase()}</span> }
